 39:  36: function Invoke-McpYamlFileOperation {
 40:  37:     <#
 41:  38:     .SYNOPSIS
 42:  39:         Runs a YAML file operation with retry/backoff for transient file locks.
 43:  40:     .PARAMETER Operation
 44:  41:         File-system operation to execute.
 45:  42:     #>
 46:  43:     [CmdletBinding()]
 47:  44:     param(
 48:  45:         [Parameter(Mandatory)][scriptblock]$Operation,
 49:  46:         [int]$Attempts = 8,
 50:  47:         [int]$InitialDelayMilliseconds = 25
 51:  48:     )
 52:  49: 
 53:  50:     $delay = [Math]::Max(1, $InitialDelayMilliseconds)
 54:  51:     for ($attempt = 1; $attempt -le $Attempts; $attempt++) {
 55:  52:         try {
 56:  53:             return (& $Operation)
 57:  54:         } catch [System.IO.IOException] {
 58:  55:             if ($attempt -ge $Attempts) { throw }
 59:  56:         } catch [System.UnauthorizedAccessException] {
 60:  57:             if ($attempt -ge $Attempts) { throw }
 61:  58:         }
 62:  59: 
 63:  60:         Start-Sleep -Milliseconds $delay
 64:  61:         $delay = [Math]::Min($delay * 2, 500)
 65:  62:     }
 66:  63: 
 67:  64:     throw 'YAML file operation failed after retry attempts.'
 68:  65: }
