 79:  76:     param(
 80:  77:         [Parameter(Mandatory)][string]$Path,
 81:  78:         [switch]$Create
 82:  79:     )
 83:  80: 
 84:  81:     Import-McpYamlSerializer
 85:  82:     $resolvedPath = Resolve-McpYamlFilePath -Path $Path
 86:  83:     if (-not (Test-Path -LiteralPath $resolvedPath -PathType Leaf)) {
 87:  84:         if ($Create) {
 88:  85:             return [ordered]@{}
 89:  86:         }
 90:  87: 
 91:  88:         throw "YAML file not found: $resolvedPath"
 92:  89:     }
 93:  90: 
 94:  91:     $yamlText = Invoke-McpYamlFileOperation -Operation {
 95:  92:         [System.IO.File]::ReadAllText($resolvedPath)
 96:  93:     }
 97:  94:     if ([string]::IsNullOrWhiteSpace($yamlText)) {
 98:  95:         if ($Create) {
 99:  96:             return [ordered]@{}
100:  97:         }
101:  98: 
102:  99:         throw "YAML file is empty: $resolvedPath"
103: 100:     }
104: 101: 
105: 102:     return (ConvertFrom-Yaml -Yaml $yamlText -Ordered -ErrorAction Stop)
106: 103: }
